from collections import deque

def getcomps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if col==0 or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c));p=[]
   while q:
    x,y=q.pop();p.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and g[a][b]==col and (a,b) not in seen:seen.add((a,b));q.append((a,b))
   out.append((col,p))
 return out

def gravity(g,d):
 h,w=len(g),len(g[0]); comps=getcomps(g)
 boundary={(r,c) for r in range(h) for c in range(w) if len(set(g[r]))==1 and g[r][0]!=0}
 if d==-1: comps.sort(key=lambda x:min(r for r,c in x[1]))
 else: comps.sort(key=lambda x:max(r for r,c in x[1]),reverse=True)
 fixed=set(boundary); out=[[0]*w for _ in range(h)]
 for color,pts in comps:
  shift=0
  while True:
   trial=[(r+shift+d,c) for r,c in pts]
   if any(not(0<=r<h) or (r,c) in fixed for r,c in trial): break
   shift+=d
  moved=[(r+shift,c) for r,c in pts]
  assert not any((r,c) in fixed for r,c in moved)
  fixed.update(moved)
  for r,c in moved:out[r][c]=color
 for r,c in boundary:out[r][c]=g[r][c]
 return out

